replacements.new:
vec2 grid = surface_uv / vec2(bay_width, floor_height);
vec2 within = fract(grid);
vec2 aa = min(fwidth(grid) * 1.25, vec2(.12));
// Cells the pixel footprint spans. Below two pixels per cell the window
// pattern is past Nyquist: which cell a pixel lands in stops describing the
// building and starts describing where the pixel centre happened to fall,
// which is exactly what makes a distant facade sparkle as the camera moves.
// Past that point each per-cell random is faded to its own expectation, so
// the wall converges to the average window instead of one arbitrary one.
// Either axis being undersampled spoils the cell index, so the worst wins.
float cells_per_pixel = max(fwidth(grid.x), fwidth(grid.y));
float cell_detail = 1.0 - smoothstep(.5, 1.0, cells_per_pixel);
float pane_detail = interval(within.x, pane_bounds.x, pane_bounds.y, aa.x)
                  * interval(within.y, pane_bounds.z, pane_bounds.w, aa.y);
// A pane's mean over its cell is just the fraction of the cell it covers.
float pane_mean = max(pane_bounds.y - pane_bounds.x, 0.0)
                * max(pane_bounds.w - pane_bounds.z, 0.0);
float pane = mix(pane_mean, pane_detail, cell_detail);
vec2 cell = floor(grid);
float occupancy_sample = hash21(cell + facade_style * 31.7);
// hash21 is uniform on [0,1), so E[step(t, u)] is 1 - t, and never below
// zero: a threshold above one means a facade whose windows are never lit.
float occupied = mix(
    clamp(1.0 - occupancy_threshold, 0.0, 1.0),
    step(occupancy_threshold, occupancy_sample),
    cell_detail
);

