replacements.new:
const float DIM_LOW = .24;
float room_dimmer = mix(
    (DIM_LOW + 1.0) * .5,
    mix(DIM_LOW, 1.0, hash21(cell * vec2(1.31, 2.17) + facade_style * 9.1)),
    cell_detail
);
const float BLACKOUT_THRESHOLD = .12;
float floor_blackout = mix(
    1.0 - BLACKOUT_THRESHOLD,
    step(
        BLACKOUT_THRESHOLD,
        hash21(vec2(floor(cell.y / 3.0), facade_style * 13.7))
    ),
    cell_detail
);
occupied *= room_dimmer * floor_blackout;
float temperature = mix(
    .5, hash21(cell + facade_style * 17.0 + 11.3), cell_detail
);

