replacements.new:
// Blind and curtain phases repeat within a cell, so they are finer than the
// cell and fade on the same footprint test. Their means come from the same
// edges the smoothsteps use rather than being written down separately: for
// a phase uniform on [0,1), E[smoothstep(a,b,u)] is 1 - (a+b)/2, and the
// curtain split is uniform on [0,0.5), which halves the interval it spans.
const vec2 BLIND_EDGES = vec2(.16, .31);
const vec2 CURTAIN_EDGES = vec2(.16, .28);
float blind_phase = fract(room_within.y * 11.0 + temperature * .37);
float blind_shape = mix(
    1.0 - (BLIND_EDGES.x + BLIND_EDGES.y) * .5,
    smoothstep(BLIND_EDGES.x, BLIND_EDGES.y, blind_phase),
    cell_detail
);
float blinds = mix(.52, 1.0, blind_shape);
float curtain_split = abs(room_within.x - .5);
float curtain_shape = mix(
    ((.5 - CURTAIN_EDGES.y) + (CURTAIN_EDGES.y - CURTAIN_EDGES.x) * .5) / .5,
    smoothstep(CURTAIN_EDGES.x, CURTAIN_EDGES.y, curtain_split),
    cell_detail
);
float curtains = mix(.58, 1.0, curtain_shape);
